m=json.load(open('/app/output/hover_left_floor_drill_02/meta.json'));c=m['cameras']['robot_r1:left_realsense_link:Camera:0'];K=np.array(c['intrinsic_cv']);E=np.array(c['extrinsic_cv']);R=E[:,:3];C=-R.T@E[:,3];e=np.array(m['proprio']['now'][35:38]);print('C',C,'eef',e)
def ray(p):return R.T@np.linalg.inv(K)@np.array([p[0],p[1],1.])
for h in [(170,145),(175,145),(165,140),(170,150),(160,140)]:
 z=.65;W=C+(z-C[2])/ray(h)[2]*ray(h);print('\nhandle',h,'world',W)
 for g in [(112,130),(112,140),(125,135),(120,145)]:
  rg=ray(g);Cn=W-(z-C[2])/rg[2]*rg;print(' gap',g,'dc',Cn-C,'eefnew',e+Cn-C)
